CREATE TABLE ezcontentclass_attribute_ml (contentclass_attribute_id INTEGER NOT NULL, version INTEGER NOT NULL, language_id BIGINT NOT NULL, name VARCHAR(255) NOT NULL, description CLOB DEFAULT NULL, data_text CLOB DEFAULT NULL, data_json CLOB DEFAULT NULL, PRIMARY KEY(contentclass_attribute_id, version, language_id), CONSTRAINT ezcontentclass_attribute_ml_lang_fk FOREIGN KEY (language_id) REFERENCES ezcontent_language (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE);
